r"""Write maps/<level>_survival.gsc, a survival level's data, from a CoDOL survival addon.

Survival is its own match category on the unchanged multiplayer level
(docs/CODOL_SURVIVAL_PLAN.md): the entities the CoDOL survival builds
authored in their coop_survival_<level>.ff addon_map_ents -- the player starts,
IW5's squad leader/follower structs, the kiosks, the dog spawners, the
claymore and care-package spots, the boss chopper paths -- are the mode's
data, so they live in the script tree as one GSC per level instead of a zone.

Input: the addon's entity text, decoded from the later build's zone:

    CodolSoundDumper decrypt --input "<2.6.9.7>\IIPS\IIPSDownload|client_shipRetail/chinese/coop_survival_mp_fav_tropical.ff" --out fav.zone
    python tools/objective_ents.py extract fav.zone fav_ents.txt
    python tools/survival_ents.py fav_ents.txt mp_fav_tropical [--out DIR]

DIR defaults to bin/home/codol_rawfiles/maps.  The 2.6.9.7 addons are the
source of choice: 3.5.2.6's add "survivalPlus" content whose *N brush models
the 1.1.1.13 levels lack; this tool drops every survivalPlus entity and every
brush model either way.
"""
import argparse
import re
import os
import sys

HERE = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, HERE)
from objective_ents import parse  # noqa: E402

OUT = os.path.join(os.path.dirname(HERE), "bin", "home", "codol_rawfiles", "maps", "mp", "survival")
LEVELS = os.path.join(os.path.dirname(HERE), "bin", "home", "codol_rawfiles", "maps", "mp")


def vec(text, default="0 0 0"):
    parts = (text or default).split()
    vals = []
    for p in parts[:3]:
        t = ("%.3f" % float(p)).rstrip("0").rstrip(".")  # GSC takes no exponents
        vals.append("0" if t in ("", "-0") else t)
    while len(vals) < 3:
        vals.append("0")
    return "( %s, %s, %s )" % tuple(vals)


def minimap_material(level):
    """The compass material the level's multiplayer script names (its
    maps\\mp\\_compass::setupMiniMap call), else compass_map_<level>."""
    path = os.path.join(LEVELS, "%s.gsc" % level)
    if os.path.exists(path):
        text = open(path, encoding="utf-8", errors="replace").read()
        m = re.search(r'setupMiniMap\(\s*"([^"]+)"', text)
        if m:
            return m.group(1)
    return "compass_map_%s" % level


def load(path):
    text = open(path, encoding="latin1").read()
    ents = []
    for e in parse(text):
        d = {}
        for k, v in e:
            d[k] = v
        if d.get("script_gameobjectname") == "survivalPlus":
            continue
        if d.get("model", "").startswith("*"):
            continue
        ents.append(d)
    return ents


def build(ents, level, source):
    by_target = {}
    for e in ents:
        if e.get("targetname"):
            by_target.setdefault(e["targetname"], []).append(e)
    starts = [e for e in ents if e.get("classname", "").startswith("info_player_start_so")]
    leaders = [e for e in ents if e.get("classname") == "script_struct" and e.get("script_noteworthy") == "leader"
               and "protector" not in e.get("targetname", "")]
    kiosks = [e for e in ents if e.get("targetname") in ("kiosk_locker", "kiosk_killstreak")]
    dogs = [e for e in ents if e.get("targetname") == "dog_spawner" or e.get("classname", "").startswith("actor_enemy_dog")]
    claymores = [e for e in ents if e.get("targetname") in ("so_claymore_loc", "survival_claymore_loc")]
    packages = [e for e in ents if e.get("script_noteworthy") == "so_carepackage_loc"]
    chopper_starts = [e for e in ents if e.get("targetname") in ("chopper_boss_path_start", "drop_path_start")]
    heli = [e for e in ents if e.get("classname") == "script_struct_heli"]

    out = []
    w = out.append
    w("// maps/mp/survival/%s -- Spec Ops Survival's data for %s." % (level, level))
    w("//")
    w("// GENERATED by tools/survival_ents.py from %s." % source)
    w("// maps\\mp\\gametypes\\_survival_levels::data() calls data() for the running level")
    w("// (survival plays on the multiplayer script chain; the level script is the")
    w("// map's MP one).  The entities come from the CoDOL survival addon for this")
    w("// level: IW5's info_player_start_so, the squad leader/follower structs,")
    w("// CoDOL's kiosks, the dog spawners, the claymore and care-package spots and")
    w("// the boss chopper path starts.  Regenerate rather than edit.")
    w("")
    w("spot( origin, angles )")
    w("{")
    w("\ts = spawnStruct();")
    w("\ts.origin = origin;")
    w("\ts.angles = angles;")
    w("\treturn s;")
    w("}")
    w("")
    w("kiosk( kind, origin, angles )")
    w("{")
    w("\ts = spot( origin, angles );")
    w("\ts.kind = kind;")
    w("\treturn s;")
    w("}")
    w("")
    w("data()")
    w("{")
    w("\tlevel.survival_player_starts = [];")
    for e in starts:
        w("\tlevel.survival_player_starts[ level.survival_player_starts.size ] = spot( %s, %s );"
          % (vec(e.get("origin")), vec(e.get("angles"))))
    w("")
    w("\t// IW5 _squad_enemies: a leader and the followers it targets.")
    w("\tlevel.survival_leaders = [];")
    for e in leaders:
        w("\tl = spot( %s, %s );" % (vec(e.get("origin")), vec(e.get("angles"))))
        w("\tl.followers = [];")
        for f in by_target.get(e.get("target", ""), []) if e.get("target") else []:
            if f is e:
                continue
            w("\tl.followers[ l.followers.size ] = spot( %s, %s );"
              % (vec(f.get("origin")), vec(f.get("angles"), e.get("angles", "0 0 0"))))
        w("\tlevel.survival_leaders[ level.survival_leaders.size ] = l;")
    w("")
    w("\tlevel.survival_kiosk_spots = [];")
    for e in kiosks:
        w("\tlevel.survival_kiosk_spots[ level.survival_kiosk_spots.size ] = kiosk( \"%s\", %s, %s );"
          % (e["targetname"], vec(e.get("origin")), vec(e.get("angles"))))
    w("")
    w("\tlevel.survival_dog_spots = [];")
    for e in dogs:
        w("\tlevel.survival_dog_spots[ level.survival_dog_spots.size ] = spot( %s, %s );"
          % (vec(e.get("origin")), vec(e.get("angles"))))
    w("")
    w("\tlevel.survival_claymore_spots = [];")
    for e in claymores:
        w("\tlevel.survival_claymore_spots[ level.survival_claymore_spots.size ] = spot( %s, ( 0, 0, 0 ) );"
          % vec(e.get("origin")))
    w("")
    w("\tlevel.survival_carepackage_spots = [];")
    for e in packages:
        w("\tlevel.survival_carepackage_spots[ level.survival_carepackage_spots.size ] = spot( %s, ( 0, 0, 0 ) );"
          % vec(e.get("origin")))
    w("")
    w("\tlevel.survival_chopper_starts = [];")
    for e in chopper_starts:
        w("\ts = spot( %s, %s );" % (vec(e.get("origin")), vec(e.get("angles"))))
        w("\ts.kind = \"%s\";" % e["targetname"])
        w("\tlevel.survival_chopper_starts[ level.survival_chopper_starts.size ] = s;")
    w("")
    w("\t// IW5's helicopter path structs (script_struct_heli): the chopper boss")
    w("\t// network (so_chopper_boss_path_struct, script_linkName/script_linkTo) and")
    w("\t// the drop paths (targetname/target chains, script_unload at the drop).")
    w("\tlevel.survival_heli_nodes = [];")
    for e in heli:
        w("\ts = spot( %s, %s );" % (vec(e.get("origin")), vec(e.get("angles"))))
        for key, field in (("targetname", "targetname"), ("target", "target"), ("script_linkName", "script_linkname"),
                           ("script_linkTo", "script_linkto"), ("script_unload", "script_unload"),
                           ("script_noteworthy", "script_noteworthy"), ("script_stopnode", "script_stopnode")):
            v = e.get(key) or e.get(key.lower())
            if v:
                w("\ts.%s = \"%s\";" % (field, v))
        w("\tlevel.survival_heli_nodes[ level.survival_heli_nodes.size ] = s;")
    w("}")
    stats = "%d starts, %d leaders (%d followers), %d kiosks, %d dog spots, %d claymore, %d care package, %d chopper starts" % (
        len(starts), len(leaders),
        sum(len([f for f in by_target.get(e.get("target", ""), []) if f is not e]) for e in leaders if e.get("target")),
        len(kiosks), len(dogs), len(claymores), len(packages), len(chopper_starts))
    return "\n".join(out) + "\n", stats


def main(argv):
    ap = argparse.ArgumentParser()
    ap.add_argument("ents")
    ap.add_argument("level")
    ap.add_argument("--out", default=OUT)
    ap.add_argument("--source", default=None, help="provenance text for the header")
    a = ap.parse_args(argv)
    ents = load(a.ents)
    text, stats = build(ents, a.level, a.source or ("CoDOL 2.6.9.7 coop_survival_%s addon_map_ents" % a.level))
    path = os.path.join(a.out, "%s.gsc" % a.level)
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(text)
    print("%s: %s" % (path, stats))
    write_dispatcher(a.out)
    return 0


def write_dispatcher(folder):
    """maps/mp/gametypes/_survival_levels.gsc: one case per level that has data."""
    levels = sorted(f[:-4] for f in os.listdir(folder) if f.endswith(".gsc"))
    out = ["// maps/mp/gametypes/_survival_levels -- which levels have survival data.",
           "//",
           "// GENERATED by tools/survival_ents.py (one case per maps/mp/survival/<level>.gsc).",
           "",
           "has_data( mapname )",
           "{",
           "	switch ( mapname )",
           "	{"]
    for l in levels:
        out.append("	case \"%s\":" % l)
    out += ["		return true;", "	}", "	return false;", "}", "", "data( mapname )", "{", "	switch ( mapname )", "	{"]
    for l in levels:
        out += ["	case \"%s\":" % l, "		maps\\mp\\survival\\%s::data();" % l, "		return true;"]
    out += ["	}", "	return false;", "}", ""]
    path = os.path.join(os.path.dirname(folder), "gametypes", "_survival_levels.gsc")
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write("\n".join(out))


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
